const solutions: Record<string, Solution> = {
  'studios-media-teams': {
    title: 'Studios & media teams', eyebrow: 'For lean production and release teams', promise: 'Keep the story alive between the trailer and the premiere.', description: 'Framewise turns a film, series, channel or media property into an autonomous short-form production desk—continuously finding audience angles, creating release-ready video and keeping connected channels active.', problem: 'Small media teams have the material and the story, but release campaigns still compete with editing, production and distribution for the same people and the same hours.', outcomes: ['Audience questions and timely cultural signals become an evidence-backed topic pipeline.', 'Trailers, behind-the-scenes stories, explainers and fan-facing formats stay balanced.', 'Every scene is scripted, generated, checked and recoverable before publication.', 'Performance from published work becomes a cautious input to the next editorial cycle.'], workflow: [{ title: 'Learn the property', text: 'Add the project website, synopsis, audience, release context, rights and brand constraints once.' }, { title: 'Research the audience moment', text: 'Parallel finds current questions, adjacent themes and primary sources instead of recycling generic prompts.' }, { title: 'Direct the right format', text: 'Gemini selects UGC, storytelling, cinematic or motion graphics and authors the complete production package.' }, { title: 'Generate and distribute', text: 'Veo produces the scenes, automated QA checks the result and connected channels receive the finished cut.' }], examples: ['Independent film release campaigns', 'Streaming and episodic social teams', 'Production-company thought leadership', 'Fan education and behind-the-scenes content'],
