  'creators-experts': {
    title: 'Creators & experts', eyebrow: 'For knowledge-led channels', promise: 'Turn expertise into a channel that keeps moving without a blank page.', description: 'Framewise learns what you know, who you help and what your audience keeps asking—then researches, scripts, generates and publishes a balanced mix of useful, entertaining and commercial videos.', problem: 'Experts rarely lack knowledge. They lack a repeatable system for turning it into strong hooks, visual stories and a reliable publishing cadence.', outcomes: ['Fresh ideas stay anchored to your expertise and audience interests.', 'The content mix prevents every video from sounding like a sales post.', 'A reusable creator profile keeps voice, role and visual direction consistent.', 'You can review scripts—or let a proven workflow continue automatically.'], workflow: [{ title: 'Map your expertise', text: 'Framewise extracts product context, audience pain, solution and searchable topic territories from your site.' }, { title: 'Find useful angles', text: 'Research combines fresh evidence with what you selected, hid and published before.' }, { title: 'Build the full script', text: 'Hooks, dialogue, character map, locations, action and detailed scene prompts are authored before video spend.' }, { title: 'Keep publishing', text: 'Budget and cadence controls determine what moves automatically and what waits for review.' }], examples: ['Coaches and consultants', 'Authors and researchers', 'Founder-led channels', 'Professional educators'],
  },
